import sqlite3

def demo(enable):
    db = sqlite3.connect(":memory:")
    if enable:
        db.execute("PRAGMA foreign_keys = ON")   # per connection, off by default
    db.executescript("""
    CREATE TABLE parent(id INTEGER PRIMARY KEY);
    CREATE TABLE child(id INTEGER PRIMARY KEY, pid INTEGER REFERENCES parent(id));
    """)
    print("foreign_keys =", db.execute("PRAGMA foreign_keys").fetchone()[0])
    try:
        db.execute("INSERT INTO child VALUES (1, 99)")   # parent 99 does not exist
        print("  orphan inserted silently")
    except sqlite3.IntegrityError as e:
        print("  rejected:", e)
    # finds existing violations: (table, rowid, parent table, fk index)
    print("  foreign_key_check:", db.execute("PRAGMA foreign_key_check").fetchall())
    print("  foreign_key_list:", db.execute("PRAGMA foreign_key_list(child)").fetchall()[0][2:5])

demo(False)
demo(True)

import sqlite3

