import sqlite3

db = sqlite3.connect(":memory:")
db.execute("PRAGMA foreign_keys = ON")
db.executescript("""
CREATE TABLE posts(id INTEGER PRIMARY KEY, title TEXT);
CREATE TABLE photos(id INTEGER PRIMARY KEY, url TEXT);
-- exclusive arc: one real FK per target, exactly one of them set
CREATE TABLE comments(id INTEGER PRIMARY KEY, body TEXT,
  post_id  INTEGER REFERENCES posts(id)  ON DELETE CASCADE,
  photo_id INTEGER REFERENCES photos(id) ON DELETE CASCADE,
  CHECK ((post_id IS NOT NULL) + (photo_id IS NOT NULL) = 1));
INSERT INTO posts VALUES (1,'Hello');
INSERT INTO photos VALUES (1,'p.png');
INSERT INTO comments(body, post_id) VALUES ('nice post', 1);
INSERT INTO comments(body, photo_id) VALUES ('nice photo', 1);
""")
for sql in ["INSERT INTO comments(body) VALUES ('no target')",
            "INSERT INTO comments(body, post_id, photo_id) VALUES ('two targets', 1, 1)",
            "INSERT INTO comments(body, post_id) VALUES ('orphan', 99)"]:
    try:
        db.execute(sql)
    except sqlite3.IntegrityError as e:
        print("rejected:", sql[:42], "->", e)
db.execute("DELETE FROM posts WHERE id = 1")           # cascades only to its comments
print(db.execute("SELECT body FROM comments").fetchall())
